function groupAnagrams(strs) {
  const map = {};
  for (let s of strs) {
    const key = s.split("").sort().join("");
    if (!map[key]) map[key] = [];
    map[key].push(s);
  }
  return Object.values(map);
}

const groupAnagrams = (strs: string[]): string[][] => {
    const map = new Map<string, string[]>();
    for (const s of strs) {
        const key = s.split("").sort().join("");
        if (!map.has(key)) map.set(key, []);
        map.get(key)!.push(s);
    }
    return [...map.values()];
};

