function isValidParentheses(s) {
  const stack = [];
  const pairs = { "(": ")", "[": "]", "{": "}" };
  for (let c of s) {
    if (c in pairs) stack.push(c);
    else if (pairs[stack.pop()] !== c) return false;
  }
  return stack.length === 0;
}

