function findDuplicates(nums: number[]): number[] {
    const seen = new Set<number>();
    const dupes = new Set<number>();
    for (const n of nums) {
        if (seen.has(n)) dupes.add(n);
        seen.add(n);
    }
    return [...dupes];
}

